}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain any leftover notifications from other tests (static queue)
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain the queue after each test to avoid pollution
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_EnqueuesNotification_CanBeReceived()
    {
        // Act
        _sut.SendNotification("Student", "1", EntityOperation.CREATE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithDisplayName_GeneratesCorrectMessage()
    {
        // Act
        _sut.SendNotification("Course", "42", "Calculus", EntityOperation.CREATE, "teacher");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("New Course 'Calculus' has been created", notification.Message);
        Assert.Equal("teacher", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        // Act
        _sut.SendNotification("Student", "5", EntityOperation.DELETE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student (ID: 5) has been deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        // Act
        _sut.SendNotification("Department", "1", EntityOperation.UPDATE, null);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithoutUserName_DefaultsToSystem()
    {
        // Act
        _sut.SendNotification("Department", "1", EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "New Student (ID: 1) has been created")]
    [InlineData(EntityOperation.UPDATE, "Student (ID: 1) has been updated")]
    [InlineData(EntityOperation.DELETE, "Student (ID: 1) has been deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessages(EntityOperation operation, string expectedMessage)
    {
        // Act
        _sut.SendNotification("Student", "1", operation);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal(expectedMessage, notification.Message);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        // Act
        var notification = _sut.ReceiveNotification();

        // Assert
        Assert.Null(notification);
    }

    [Fact]
    public void ReceiveNotification_FifoOrder()
    {
        // Arrange
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);
        _sut.SendNotification("Course", "2", EntityOperation.UPDATE);
        _sut.SendNotification("Department", "3", EntityOperation.DELETE);

        // Act & Assert
        var first = _sut.ReceiveNotification();
        Assert.Equal("Student", first!.EntityType);
        Assert.Equal("1", first.EntityId);

        var second = _sut.ReceiveNotification();
        Assert.Equal("Course", second!.EntityType);
        Assert.Equal("2", second.EntityId);

        var third = _sut.ReceiveNotification();
        Assert.Equal("Department", third!.EntityType);
        Assert.Equal("3", third.EntityId);

        Assert.Null(_sut.ReceiveNotification());
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // Act & Assert - MarkAsRead is a no-op but should not throw
        var exception = Record.Exception(() => _sut.MarkAsRead(999));
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToCurrentTime()
    {
        // Arrange
        var before = DateTime.Now;

        // Act
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        // Assert
        var after = DateTime.Now;
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void SendNotification_QueueOverflow_OldestItemsRemoved()
    {
        // Arrange - fill the queue beyond the 500 limit
        for (int i = 0; i < 510; i++)
        {
            _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE, "user");
        }

        // Act - count remaining items
        int count = 0;
        while (_sut.ReceiveNotification() != null) count++;

        // Assert - should be at most 500 due to the cap
        Assert.True(count <= 500, $"Queue should have at most 500 items but had {count}");
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesIdInMessage()
    {
        // Act
        _sut.SendNotification("Instructor", "7", "", EntityOperation.UPDATE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor (ID: 7) has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithWhitespaceDisplayName_UsesIdInMessage()
    {
        // Act
        _sut.SendNotification("Instructor", "7", "   ", EntityOperation.UPDATE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor (ID: 7) has been updated", notification.Message);
    }
}

