using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        SeedData();
        _controller = new InstructorsController(_context);
    }

    private void SeedData()
    {
        var dept = new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000, StartDate = new DateTime(2010, 1, 1) };
        _context.Departments.Add(dept);

        var course1 = new Course { CourseID = 101, Title = "Intro to CS", Credits = 3, DepartmentID = 1, Enrollments = new List<Enrollment>() };
        var course2 = new Course { CourseID = 102, Title = "Data Structures", Credits = 4, DepartmentID = 1, Enrollments = new List<Enrollment>() };
        _context.Courses.AddRange(course1, course2);

        var instructor1 = new Instructor
        {
            ID = 20,
            LastName = "Smith",
            FirstMidName = "John",
            HireDate = new DateTime(2010, 1, 1),
            CourseAssignments = new List<CourseAssignment>(),
            OfficeAssignment = new OfficeAssignment { InstructorID = 20, Location = "Room 101" }
        };
        var instructor2 = new Instructor
        {
            ID = 21,
            LastName = "Jones",
            FirstMidName = "Jane",
            HireDate = new DateTime(2015, 6, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.AddRange(instructor1, instructor2);
        _context.SaveChanges();

        // Add course assignments
        _context.CourseAssignments.Add(new CourseAssignment { InstructorID = 20, CourseID = 101 });
        _context.CourseAssignments.Add(new CourseAssignment { InstructorID = 20, CourseID = 102 });

        // Add enrollment
        var student = new Student { ID = 50, LastName = "Doe", FirstMidName = "Jack", EnrollmentDate = new DateTime(2021, 9, 1) };
        _context.Students.Add(student);
        _context.Enrollments.Add(new Enrollment { EnrollmentID = 1, CourseID = 101, StudentID = 50, Grade = Grade.A });
        _context.SaveChanges();
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

