using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.TestHelpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new NotificationsController(_context);
        // Drain the static queue to avoid pollution from other tests
        while (_controller.GetNotifications() is JsonResult jr)
        {
            var value = jr.Value;
            var countProp = value?.GetType().GetProperty("count");
            if (countProp != null)
            {
                var count = (int)countProp.GetValue(value)!;
                if (count == 0) break;
            }
            else break;
        }
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsView()
    {
        // Act
        var result = _controller.Index();

        // Assert
        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
    {
        // Act
        var result = _controller.GetNotifications();

        // Assert
        Assert.IsType<JsonResult>(result);
        var value = result.Value;
        Assert.NotNull(value);
        var successProp = value.GetType().GetProperty("success");
        Assert.NotNull(successProp);
        Assert.True((bool)successProp.GetValue(value)!);
        var countProp = value.GetType().GetProperty("count");
        Assert.NotNull(countProp);
        Assert.Equal(0, (int)countProp.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotifications()
    {
        // Arrange - Send some notifications via the controller's notification service
        _controller.notificationService.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "admin");
        _controller.notificationService.SendNotification("Course", "2", "Test Course", EntityOperation.UPDATE, "admin");

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var value = result.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(2, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_LimitsTo10()
    {
        // Arrange - Send 15 notifications
        for (int i = 0; i < 15; i++)
        {
            _controller.notificationService.SendNotification("Entity", i.ToString(), EntityOperation.CREATE, "admin");
        }

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var value = result.Value!;
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(10, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccess()
    {
        // Act
        var result = _controller.MarkAsRead(1);

        // Assert
        Assert.IsType<JsonResult>(result);
        var value = result.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);
    }

    [Fact]
    public void MarkAsRead_NonExistentId_StillReturnsSuccess()
    {
        // Act (MarkAsRead is a no-op in current implementation)
        var result = _controller.MarkAsRead(99999);

        // Assert
        var value = result.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_AfterReceiving_QueueIsDrained()
    {
        // Arrange
        _controller.notificationService.SendNotification("Student", "1", EntityOperation.CREATE);
        _controller.notificationService.SendNotification("Course", "2", EntityOperation.UPDATE);

        // Act - first call drains the queue
        _controller.GetNotifications();

        // Act - second call should show empty
        var result = _controller.GetNotifications();

        // Assert
        var value = result.Value!;
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(0, (int)countProp!.GetValue(value)!);
    }
}

